import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import ProductCarousel from './ProductCarousel';
import './ProductShowcase.css';

const ProductShowcase = ({ onAddToCart }) => {
  const [categories, setCategories] = useState([]);
  const [products, setProducts] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const categoryRefs = useRef({});

  // Buscar categorias e produtos
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        console.log('📡 Buscando categorias de: http://localhost:3001/api/categories');
        console.log('📡 Buscando produtos de: http://localhost:3001/api/products');

        // Chamar as APIs CORRETAS
        const categoriesRes = await axios.get('http://localhost:3001/api/categories');
        const productsRes = await axios.get('http://localhost:3001/api/products');

        console.log('✅ Categorias recebidas:', categoriesRes.data);
        console.log('✅ Produtos recebidos:', productsRes.data);

        setCategories(categoriesRes.data || []);
        setProducts(productsRes.data || []);

        // Selecionar primeira categoria por padrão
        if (categoriesRes.data && categoriesRes.data.length > 0) {
          setSelectedCategory(categoriesRes.data[0].id);
        }
      } catch (err) {
        console.error('❌ Erro ao buscar dados:', err.response?.data || err.message);
        console.error('URL tentada:', err.config?.url);
        setError(`Erro ao carregar produtos: ${err.message}`);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Filtrar produtos por categoria e busca
  const getFilteredProducts = (categoryId) => {
    return products
      .filter((p) => p.category_id === categoryId)
      .filter((p) =>
        p.name.toLowerCase().includes(searchTerm.toLowerCase())
      );
  };

  // Scroll suave para categoria clicada
  const handleCategoryClick = (categoryId) => {
    setSelectedCategory(categoryId);

    // Scroll suave para a seção da categoria
    setTimeout(() => {
      const ref = categoryRefs.current[categoryId];
      if (ref) {
        ref.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }, 0);
  };

  if (loading) {
    return (
      <div className="showcase-container">
        <div className="loading">Carregando produtos... ⏳</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="showcase-container">
        <div className="error">
          ❌ {error}
          <p style={{ fontSize: '0.9rem', marginTop: '1rem' }}>
            Verifique se o backend está rodando em http://localhost:3001
          </p>
        </div>
      </div>
    );
  }

  if (categories.length === 0 || products.length === 0) {
    return (
      <div className="showcase-container">
        <div className="no-data">⚠️ Nenhuma categoria ou produto disponível.</div>
      </div>
    );
  }

  return (
    <div className="showcase-container">
      {/* Barra de pesquisa */}
      <div className="search-section">
        <div className="search-bar">
          <input
            type="text"
            placeholder="🔍 Buscar produtos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
      </div>

      {/* Categorias fixas no topo */}
      <div className="categories-sticky">
        <div className="categories-wrapper">
          {categories.length > 0 && (
            <>
              <button
                className="category-btn category-scroll-btn-left"
                onClick={() => {
                  const container = document.querySelector('.categories-scroll');
                  if (container) container.scrollBy({ left: -200, behavior: 'smooth' });
                }}
                aria-label="Scroll left"
              >
                ⬅️
              </button>

              <div className="categories-scroll">
                {categories.map((category) => (
                  <button
                    key={category.id}
                    className={`category-btn ${
                      selectedCategory === category.id ? 'active' : ''
                    }`}
                    onClick={() => handleCategoryClick(category.id)}
                  >
                    {category.name}
                    <span className="category-count">
                      ({getFilteredProducts(category.id).length})
                    </span>
                  </button>
                ))}
              </div>

              <button
                className="category-btn category-scroll-btn-right"
                onClick={() => {
                  const container = document.querySelector('.categories-scroll');
                  if (container) container.scrollBy({ left: 200, behavior: 'smooth' });
                }}
                aria-label="Scroll right"
              >
                ➡️
              </button>
            </>
          )}
        </div>
      </div>

      {/* Seções de categorias com carrossel */}
      <div className="products-section">
        {categories.map((category) => {
          const categoryProducts = getFilteredProducts(category.id);

          return (
            <div
              key={category.id}
              ref={(el) => (categoryRefs.current[category.id] = el)}
              className="category-carousel-section"
            >
              {categoryProducts.length > 0 ? (
                <ProductCarousel
                  categoryName={category.name}
                  products={categoryProducts}
                  onAddToCart={onAddToCart}
                />
              ) : (
                <div className="category-section">
                  <h2 className="category-title">📦 {category.name}</h2>
                  <p className="no-products">
                    Nenhum produto encontrado nesta categoria.
                  </p>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Mensagem se nenhum produto encontrado após busca */}
      {searchTerm &&
        products.filter((p) =>
          p.name.toLowerCase().includes(searchTerm.toLowerCase())
        ).length === 0 && (
          <div className="no-results">
            <p>😕 Nenhum produto encontrado com "{searchTerm}"</p>
            <button
              className="clear-search-btn"
              onClick={() => setSearchTerm('')}
            >
              Limpar busca
            </button>
          </div>
        )}
    </div>
  );
};

export default ProductShowcase;
